import { generateDynamicFAQs } from '@/lib/seo/contentEngine';

/**
 * Visible FAQ for the programmatic calculator pages.
 *
 * Deliberately emits no FAQPage JSON-LD. These questions are generated by
 * substituting a number into a fixed template — "Werden bei 100 Tagen auch
 * Wochenenden mitgezählt?" differs from the 90-day page only in the numeral.
 * Marking up hundreds of pages with structurally identical Q&A is exactly the
 * mass-duplication that structured data is not for, and it would be asserting
 * distinctness the content does not have.
 *
 * It also buys nothing: FAQ rich results are limited to well-known
 * authoritative government and health sites, so this markup earns no SERP
 * feature on a calculator page. Removing it costs no visibility and removes a
 * duplication signal.
 *
 * FAQPage markup is retained where the questions are written per page rather
 * than generated: the homepage and the four tool hubs.
 */
export function FAQBlock({ intent, slug, locale }: { intent: string; slug: string; locale: string }) {
    const match = slug.match(/^(\d+)-/);
    const numValue = match ? parseInt(match[1]) : undefined;
    const faqs = generateDynamicFAQs(intent, slug, locale, numValue);

    return (
        <section className="bg-white border border-slate-200 rounded-xl p-6 md:p-8">
            <h2 className="text-2xl font-bold mb-8 text-slate-900">
                {locale === 'de' ? 'Häufig gestellte Fragen (FAQ)' : 'Frequently Asked Questions (FAQ)'}
            </h2>

            <div className="space-y-6">
                {faqs.map((faq, index) => (
                    <div key={index} className="space-y-2 pb-6 border-b border-slate-100 last:border-0 last:pb-0">
                        <h3 className="text-lg font-semibold text-slate-900">{faq.question}</h3>
                        <p className="text-slate-700 leading-relaxed">{faq.answer}</p>
                    </div>
                ))}
            </div>
        </section>
    );
}
